/**
 * USIR Linguistic Gates OPEN-01 / OPEN-02 / OPEN-04 (TypeScript port).
 *
 * Numeric reference: python/usir_py/linguistic_gates.py (Py/TS parity fixture:
 * tests/fixtures/open_gates_parity.json, generated by scripts/gen_open_gates_fixture.py).
 *
 * Parser-free by design: every function receives exactly what the Python function
 * receives (plain strings, pre-extracted `tail` strings, scope flags, numeric arrays).
 * No morphological analyser / dependency parser is needed or invoked in TS; the caller
 * (e.g. a syntax driver) supplies the tail string and the negation/speculative scope flags.
 *
 * Not ported: OPEN-03 (mimetic synthesis; out of Phase 26.4 scope).
 * No author/character/work-specific vocabulary appears in any dictionary below.
 * Offsets in OPEN-04 are counted in Unicode code points (as in Python), not UTF-16 units.
 */

// ---------------------------------------------------------------------------
// OPEN-01: concreteness C(u) and polysemy tri-state damping
// ---------------------------------------------------------------------------

export const ABSTRACT_STEM_MARKERS: readonly string[] = [
  '性', '化', '的', '論', '主義', '構造', '概念', '制度',
  '単位', '課題', '側面', '関係', '問題', '状況', '機能',
  '傾向', '状態', '基準', '定義', '方針', '視線', '態度',
  '思惑', '意識', '立場', '印象', '理論', '思想', '原則',
];

const clip = (x: number, lo: number, hi: number): number => Math.min(Math.max(x, lo), hi);

/** Concept concreteness C(u) in [0, 1]. Mirrors compute_concreteness. */
export function computeConcreteness(
  surface: string,
  lemma = '',
  sensoryVec: ArrayLike<number> | null = null,
): number {
  const word = lemma ? lemma : surface;
  const isAbstract = ABSTRACT_STEM_MARKERS.some((m) => word.includes(m));
  let normInf = 0;
  let normL1 = 0;
  if (sensoryVec && sensoryVec.length > 0) {
    for (let i = 0; i < sensoryVec.length; i++) {
      const a = Math.abs(sensoryVec[i]!);
      if (a > normInf) normInf = a;
      normL1 += a;
    }
  }
  if (isAbstract) {
    const c = normL1 > 0 ? 0.15 * (normL1 / 8.0) : 0.1;
    return clip(c, 0.02, 0.28);
  }
  return clip(0.35 + 0.65 * normInf, 0.35, 1.0);
}

export type PolysemyCase =
  | 'case1_physical'
  | 'case2_synesthetic_metaphor'
  | 'case3_abstract_transfer'
  | 'case_transition'
  | 'mimetic_immunity';

export interface PolysemyGateResult {
  case: PolysemyCase;
  slot: 'primary_physical' | 'secondary_abstract';
  effectiveSensory: number[];
  dampingFactor: number;
  metaphorBonus: number;
  concretenessU: number;
}

/** Tri-state resolution on dependency edge (u -> v). Mirrors apply_open01_polysemy_damping. */
export function applyOpen01PolysemyDamping(
  uConcreteness: number,
  vPrimaryVec: ArrayLike<number>,
  vSecondaryVec: ArrayLike<number> | null = null,
  uSensoryVec: ArrayLike<number> | null = null,
  vIsMimetic = false,
): PolysemyGateResult {
  const vPri = Array.from(vPrimaryVec);
  const vSec = vSecondaryVec ? Array.from(vSecondaryVec) : vPri.map((x) => x * 0.3);
  const cU = clip(uConcreteness, 0, 1);

  if (vIsMimetic) {
    return {
      case: 'mimetic_immunity', slot: 'primary_physical', effectiveSensory: vPri.slice(),
      dampingFactor: 1.0, metaphorBonus: 0.0, concretenessU: cU,
    };
  }

  let inner = 0;
  if (uSensoryVec && uSensoryVec.length > 0) {
    const u = Array.from(uSensoryVec);
    let dot = 0, nu = 0, nv = 0;
    for (let i = 0; i < u.length; i++) { dot += u[i]! * vPri[i]!; nu += u[i]! * u[i]!; }
    for (let i = 0; i < vPri.length; i++) nv += vPri[i]! * vPri[i]!;
    inner = dot / (Math.sqrt(nu) * Math.sqrt(nv) + 1e-9);
  }

  if (cU < 0.45 && inner > 0.25) {
    return {
      case: 'case2_synesthetic_metaphor', slot: 'primary_physical', effectiveSensory: vPri.slice(),
      dampingFactor: 1.0, metaphorBonus: 0.35, concretenessU: cU,
    };
  }
  if (cU >= 0.45) {
    return {
      case: 'case1_physical', slot: 'primary_physical', effectiveSensory: vPri.slice(),
      dampingFactor: 1.0, metaphorBonus: 0.0, concretenessU: cU,
    };
  }
  if (cU < 0.30) {
    return {
      case: 'case3_abstract_transfer', slot: 'secondary_abstract',
      effectiveSensory: vSec.map((x) => x * cU),
      dampingFactor: cU, metaphorBonus: 0.0, concretenessU: cU,
    };
  }
  const alpha = (cU - 0.30) / 0.15;
  const blended = vPri.map((p, i) => alpha * p + (1.0 - alpha) * (vSec[i]! * cU));
  return {
    case: 'case_transition',
    slot: alpha >= 0.5 ? 'primary_physical' : 'secondary_abstract',
    effectiveSensory: blended,
    dampingFactor: alpha + (1.0 - alpha) * cU,
    metaphorBonus: 0.0,
    concretenessU: cU,
  };
}

// ---------------------------------------------------------------------------
// OPEN-02: modality coefficient and dual sensory tensor (s+, s-)
// ---------------------------------------------------------------------------

export const NEGATION_PATTERNS: readonly string[] = [
  'ないで', 'なかった', 'なければ', 'ない', 'ぬ', 'ず', 'まい',
  'なし', '消え', '失わ', 'などなかった', 'わけではない', 'ではない',
  'じゃなく', 'なく', '無かった', 'ゼロ',
];

export const SPECULATIVE_PATTERNS: readonly string[] = [
  'だろう', 'でしょう', 'かもしれない', 'かのよう', 'みたい',
  'らしい', '思われ', 'と思われる', 'ようだ', 'ように', '気配',
  '彷彿', 'ごとし', 'ごとく',
];

/** Modality coefficient alpha_mod: negation -0.5, speculative +0.6, affirmative +1.0. */
export function evaluateModalityAlpha(
  tail: string,
  isNegationScope = false,
  isSpeculativeScope = false,
): number {
  if (isNegationScope || NEGATION_PATTERNS.some((p) => tail.includes(p))) return -0.5;
  if (isSpeculativeScope || SPECULATIVE_PATTERNS.some((p) => tail.includes(p))) return 0.6;
  return 1.0;
}

export interface DualSensoryTensorResult {
  alphaMod: number;
  sPlus: number[];
  sMinus: number;
  sMinusVec: number[];
  isNegated: boolean;
  isSpeculative: boolean;
}

/** Dual sensory tensor under modality scope. Mirrors compute_dual_sensory_tensor. */
export function computeDualSensoryTensor(
  effectiveSensory: ArrayLike<number>,
  alphaMod: number,
): DualSensoryTensorResult {
  const s = Array.from(effectiveSensory);
  const pos = Math.max(0.0, alphaMod);
  const sPlus = s.map((x) => pos * x);
  let n2 = 0;
  for (const x of s) n2 += x * x;
  n2 = Math.sqrt(n2);
  const isNeg = alphaMod < 0.0;
  return {
    alphaMod,
    sPlus,
    sMinus: isNeg ? Math.abs(alphaMod) * n2 : 0.0,
    sMinusVec: isNeg ? s.map((x) => Math.abs(alphaMod) * x) : s.map(() => 0),
    isNegated: isNeg,
    isSpeculative: alphaMod > 0.0 && alphaMod < 1.0,
  };
}

// ---------------------------------------------------------------------------
// OPEN-04: Bakhtinian 2-channel separation and Dialogic Collapse
// ---------------------------------------------------------------------------

const DIALOGUE_SRC = '「([^」]+)」|『([^』]+)』';
const SPEAKER_BEFORE_RE =
  /(?:^|[。！？!?\s、でにはからのとて]|しかし|そして|だが|また)([一-龯]{1,4}|[ぁ-んァ-ヶ]{2,6}|[a-zA-Z0-9]{2,10})(?:さん|君|くん|様|氏)?(?:は|が|も)\s*(?:笑って|怒って|叫んで|頷いて|呟いて|言って|振り返って|立ち止まって|慌てて|静かに)?\s*$/u;
const SPEAKER_BEFORE_COLLOQUIAL_RE =
  /(?:^|[。！？!?\s、])([一-龯]{2,4}|[ぁ-んァ-ヶ]{2,6}|[a-zA-Z0-9]{2,10})って\s*$/u;
const SPEAKER_AFTER_RE =
  /^と(?:、)?([一-龯ぁ-んァ-ヶa-zA-Z0-9]{1,8})(?:さん|君|くん|様|氏)?(?:は|が|も)?(?:怒鳴|叫|言|語|呟|問|答|述|告|呻|応|声|笑|促|命|尋|返)/u;
const SPEAKER_VERB_AFTER_RE =
  /([一-龯ぁ-んァ-ヶa-zA-Z0-9]{1,8})(?:さん|君|くん|様|氏)?(?:は|が|も|と)(?:怒鳴|叫|言|語|呟|問|答|述|告|呻|応|声|笑|促|命|尋|返)/u;

export const SPEAKER_STOPWORDS: ReadonlySet<string> = new Set([
  '誰', '声', '言', '思', '笑', '怒', '泣', '叫', '頷', '呟', '走', '立',
  'しかし', 'そして', 'だが', 'また', 'その',
]);

export interface BakhtinianSeparationResult {
  narrationText: string;
  speakerUtterances: Map<string, string[]>;
  speakerVectors: Map<string, number[]>;
  minVoiceDistance: number;
  dialogicCollapseDetected: boolean;
  /** Entries [speakerA, speakerB, distance] in Python insertion order. */
  pairwiseDistances: Array<[string, string, number]>;
}

const cpLen = (s: string): number => Array.from(s).length;

/** Speaker from the 30-char windows before/after a quote. Mirrors extract_speaker. */
export function extractSpeaker(windowBefore: string, windowAfter: string): string | null {
  const mb = SPEAKER_BEFORE_RE.exec(windowBefore);
  if (mb) {
    const name = mb[1]!.trim();
    if (!SPEAKER_STOPWORDS.has(name) && cpLen(name) >= 1) return name;
  }
  const mc = SPEAKER_BEFORE_COLLOQUIAL_RE.exec(windowBefore);
  if (mc) {
    const name = mc[1]!.trim();
    if (!SPEAKER_STOPWORDS.has(name) && cpLen(name) >= 2) return name;
  }
  const ma = SPEAKER_AFTER_RE.exec(windowAfter);
  if (ma) {
    const name = ma[1]!.trim();
    if (!SPEAKER_STOPWORDS.has(name) && cpLen(name) >= 1) return name;
  }
  const mv = SPEAKER_VERB_AFTER_RE.exec(windowAfter);
  if (mv) {
    const name = mv[1]!.trim();
    if (!SPEAKER_STOPWORDS.has(name) && cpLen(name) >= 1) return name;
  }
  return null;
}

/** Python str.count (non-overlapping). */
function countSub(s: string, sub: string): number {
  let n = 0;
  let i = 0;
  for (;;) {
    const j = s.indexOf(sub, i);
    if (j < 0) return n;
    n++;
    i = j + sub.length;
  }
}

/** 12-D normalised stylometric vector. Mirrors compute_speech_style_vector. */
export function computeSpeechStyleVector(utterances: readonly string[]): number[] {
  if (utterances.length === 0) return new Array(12).fill(0);
  const full = utterances.join(' ');
  const chars = Array.from(full);
  const n = chars.length;
  if (n === 0) return new Array(12).fill(0);
  const nu = Math.max(utterances.length, 1);
  const sumCount = (ws: string[]): number => ws.reduce((a, w) => a + countSub(full, w), 0);

  const meanLen = n / nu;
  const exclam = sumCount(['！', '？', '!', '?']) / Math.max(n, 1);
  let kanji = 0, hira = 0, kata = 0;
  for (const c of chars) {
    const cp = c.codePointAt(0)!;
    if (cp >= 0x4e00 && cp <= 0x9fff) kanji++;
    if (cp >= 0x3040 && cp <= 0x309f) hira++;
    if (cp >= 0x30a0 && cp <= 0x30ff) kata++;
  }
  const keigo = sumCount(['です', 'ます', 'ございます', 'でしょうか', 'いたします']) / nu;
  const rough = sumCount(['だろ', 'ぜ', 'ぞ', 'じゃん', 'てめえ', '野郎', 'くそ', 'だな']) / nu;
  const ore = countSub(full, '俺') + countSub(full, 'おれ');
  const watashi = countSub(full, '私') + countSub(full, 'わたし');
  const boku = countSub(full, '僕') + countSub(full, 'ぼく');
  const pronounBalance = (ore * 1.0 - watashi * 1.0 + boku * 0.5) / nu;
  const questionP = sumCount(['のか', 'かい', 'だい', 'かしら']) / nu;
  const interj = sumCount(['あっ', 'えっ', 'うーん', 'おい', 'やれやれ']) / nu;
  const endP = sumCount(['よね', 'だよ', 'わね', 'わよ', 'だなあ']) / nu;

  return [
    Math.min(meanLen / 50.0, 2.0),
    Math.min(exclam * 20.0, 2.0),
    kanji / n,
    hira / n,
    kata / n,
    Math.min(keigo, 2.0),
    Math.min(rough, 2.0),
    clip(pronounBalance, -2.0, 2.0),
    Math.min(questionP, 2.0),
    Math.min(interj, 2.0),
    Math.min(endP, 2.0),
    Math.min(n / 200.0, 1.0),
  ];
}

/** Narration/dialogue channel split and Dialogic Collapse. Mirrors extract_dual_channel_bakhtinian. */
export function extractDualChannelBakhtinian(
  text: string,
  collapseThreshold = 0.15,
): BakhtinianSeparationResult {
  if (!text) {
    return {
      narrationText: '', speakerUtterances: new Map(), speakerVectors: new Map(),
      minVoiceDistance: 1.0, dialogicCollapseDetected: false, pairwiseDistances: [],
    };
  }
  const cps = Array.from(text);
  const speakerUtterances = new Map<string, string[]>();
  const defaults = ['Speaker_A', 'Speaker_B'];
  let dialogueIdx = 0;

  for (const m of text.matchAll(new RegExp(DIALOGUE_SRC, 'gu'))) {
    const utt = m[1] !== undefined ? m[1] : m[2];
    if (!utt) continue;
    const start = cpLen(text.slice(0, m.index!));
    const end = start + cpLen(m[0]);
    const before = cps.slice(Math.max(0, start - 30), start).join('');
    const after = cps.slice(end, Math.min(cps.length, end + 30)).join('');
    let speaker: string | null = extractSpeaker(before, after);
    if (!speaker) {
      speaker = defaults[dialogueIdx % 2]!;
      dialogueIdx++;
    }
    const list = speakerUtterances.get(speaker);
    if (list) list.push(utt); else speakerUtterances.set(speaker, [utt]);
  }

  const narration = text.replace(new RegExp(DIALOGUE_SRC, 'gu'), ' ').replace(/\s+/gu, ' ').trim();

  const speakerVectors = new Map<string, number[]>();
  for (const [spk, utts] of speakerUtterances) speakerVectors.set(spk, computeSpeechStyleVector(utts));

  const speakers = Array.from(speakerUtterances.keys());
  const pairwiseDistances: Array<[string, string, number]> = [];
  let minDist = 1.0;
  let collapse = false;
  if (speakers.length >= 2) {
    for (let i = 0; i < speakers.length; i++) {
      for (let j = i + 1; j < speakers.length; j++) {
        const v1 = speakerVectors.get(speakers[i]!)!;
        const v2 = speakerVectors.get(speakers[j]!)!;
        let s = 0;
        for (let k = 0; k < v1.length; k++) s += (v1[k]! - v2[k]!) ** 2;
        const dist = Math.sqrt(s);
        pairwiseDistances.push([speakers[i]!, speakers[j]!, dist]);
        if (dist < minDist) minDist = dist;
      }
    }
    if (minDist < collapseThreshold) collapse = true;
  }
  return {
    narrationText: narration, speakerUtterances, speakerVectors,
    minVoiceDistance: minDist, dialogicCollapseDetected: collapse, pairwiseDistances,
  };
}
